<?php
declare(strict_types=1); namespace App\Repository; use App\Entity\Course; use App\Entity\User; use Doctrine\Bundle\DoctrineBundle\Repository\ServiceEntityRepository; use Doctrine\Persistence\ManagerRegistry; /** @extends ServiceEntityRepository<Course> */ final class CourseRepository extends ServiceEntityRepository {public function __construct(ManagerRegistry $r){parent::__construct($r,Course::class);} /** @return list<Course> */ public function findForUser(User $u):array{if(in_array('ROLE_ADMIN',$u->getRoles(),true))return $this->findBy([],['name'=>'ASC']);return $this->createQueryBuilder('c')->leftJoin('c.trainers','t')->andWhere('t = :user')->setParameter('user',$u)->orderBy('c.name','ASC')->getQuery()->getResult();}}
